            "Payee" : "select ilivemessageid as \"ILiveMessageID\", vcmsgid as \"UniqueID\", vcclassname as \"Class\", dttrxntime at time zone ''Asia/Kolkata'' at time zone :timeZone as \"Time\", dobservationamount as \"Amount\", score as \"Score\",  cast(result->''score''->>''bpass'' as text)as \"FRMPass\", vcpayeraccountexternalid as \"Payer Account\", vcpayeraddr as \"PayerVPA\", vcpayeeaccountexternalid as \"Payee Account\", vcpayeeaddr as \"PayeeVPA\", null as \"FailedRule\", cast(observations->''observations''->''payerVPA''->>''vpaName'' as text) as \"PayerName\",  cast(observations->''observations''->''payeeVPA''->>''vpaName'' as text) as \"PayeeName\" from transactions.trans where vcpayeeaccountexternalid = :useraddress and (CAST(dttrxntime AS date) between CURRENT_DATE-1 and  CURRENT_DATE) order by dttrxntime desc;",
            "Both" : "select ilivemessageid as \"ILiveMessageID\", vcmsgid as \"UniqueID\", vcclassname as \"Class\", dttrxntime at time zone ''Asia/Kolkata'' at time zone :timeZone as \"Time\", dobservationamount as \"Amount\", score as \"Score\",  cast(result->''score''->>''bpass'' as text)as \"FRMPass\", vcpayeraccountexternalid as \"Payer Account\", vcpayeraddr as \"PayerVPA\", vcpayeeaccountexternalid as \"Payee Account\", vcpayeeaddr as \"PayeeVPA\", null as \"FailedRule\", cast(observations->''observations''->''payerVPA''->>''vpaName'' as text) as \"PayerName\",  cast(observations->''observations''->''payeeVPA''->>''vpaName'' as text) as \"PayeeName\" from transactions.trans where (vcpayeraccountexternalid = :useraddress or vcpayeeaccountexternalid = vcpayeraccountexternalid ) and (CAST(dttrxntime AS date) between CURRENT_DATE-1 and CURRENT_DATE) order by dttrxntime desc;"
       }
    },
    "Other":
    {
        "VPA" : {
            "Payer" : "select ilivemessageid as \"ILiveMessageID\", vcmsgid as \"UniqueID\", vcclassname as \"Class\", dttrxntime at time zone ''Asia/Kolkata'' at time zone :timeZone as \"Time\", dobservationamount as \"Amount\", score as \"Score\",  cast(result->''score''->>''bpass'' as text)as \"FRMPass\", vcpayeraccountexternalid as \"Payer Account\", vcpayeraddr as \"PayerVPA\", vcpayeeaccountexternalid as \"Payee Account\", vcpayeeaddr as \"PayeeVPA\", null as \"FailedRule\", cast(observations->''observations''->''payerVPA''->>''vpaName'' as text) as \"PayerName\",  cast(observations->''observations''->''payeeVPA''->>''vpaName'' as text) as \"PayeeName\" from transactions.trans where vcpayeraddr = :useraddress and vcclassname  = :txnClass and (CAST(dttrxntime AS date) between CURRENT_DATE-1 and  CURRENT_DATE) order by dttrxntime desc;",
            "Payee" : "select ilivemessageid as \"ILiveMessageID\", vcmsgid as \"UniqueID\", vcclassname as \"Class\", dttrxntime at time zone ''Asia/Kolkata'' at time zone :timeZone as \"Time\", dobservationamount as \"Amount\", score as \"Score\",  cast(result->''score''->>''bpass'' as text)as \"FRMPass\", vcpayeraccountexternalid as \"Payer Account\", vcpayeraddr as \"PayerVPA\", vcpayeeaccountexternalid as \"Payee Account\", vcpayeeaddr as \"PayeeVPA\", null as \"FailedRule\", cast(observations->''observations''->''payerVPA''->>''vpaName'' as text) as \"PayerName\",  cast(observations->''observations''->''payeeVPA''->>''vpaName'' as text) as \"PayeeName\" from transactions.trans where vcpayeeaddr = :useraddress and vcclassname  = :txnClass and (CAST(dttrxntime AS date) between CURRENT_DATE-1 and  CURRENT_DATE) order by dttrxntime desc;",
            "Both" : "select ilivemessageid as \"ILiveMessageID\", vcmsgid as \"UniqueID\", vcclassname as \"Class\", dttrxntime at time zone ''Asia/Kolkata'' at time zone :timeZone as \"Time\", dobservationamount as \"Amount\", score as \"Score\",  cast(result->''score''->>''bpass'' as text)as \"FRMPass\", vcpayeraccountexternalid as \"Payer Account\", vcpayeraddr as \"PayerVPA\", vcpayeeaccountexternalid as \"Payee Account\", vcpayeeaddr as \"PayeeVPA\", null as \"FailedRule\", cast(observations->''observations''->''payerVPA''->>''vpaName'' as text) as \"PayerName\",  cast(observations->''observations''->''payeeVPA''->>''vpaName'' as text) as \"PayeeName\" from transactions.trans where (vcpayeraddr = :useraddress or vcpayeeaddr = vcpayeraddr ) and vcclassname  = :txnClass and (CAST(dttrxntime AS date) between CURRENT_DATE-1 and  CURRENT_DATE) order by dttrxntime desc;"
        },
        "Account": {
            "Payer" : "select ilivemessageid as \"ILiveMessageID\", vcmsgid as \"UniqueID\", vcclassname as \"Class\", dttrxntime at time zone ''Asia/Kolkata'' at time zone :timeZone as \"Time\", dobservationamount as \"Amount\", score as \"Score\",  cast(result->''score''->>''bpass'' as text)as \"FRMPass\", vcpayeraccountexternalid as \"Payer Account\", vcpayeraddr as \"PayerVPA\", vcpayeeaccountexternalid as \"Payee Account\", vcpayeeaddr as \"PayeeVPA\", null as \"FailedRule\", cast(observations->''observations''->''payerVPA''->>''vpaName'' as text) as \"PayerName\",  cast(observations->''observations''->''payeeVPA''->>''vpaName'' as text) as \"PayeeName\" from transactions.trans where vcpayeraccountexternalid = :useraddress and vcclassname  = :txnClass and (CAST(dttrxntime AS date) between CURRENT_DATE-1 and  CURRENT_DATE) order by dttrxntime desc;",
            "Payee" : "select ilivemessageid as \"ILiveMessageID\", vcmsgid as \"UniqueID\", vcclassname as \"Class\", dttrxntime at time zone ''Asia/Kolkata'' at time zone :timeZone as \"Time\", dobservationamount as \"Amount\", score as \"Score\",  cast(result->''score''->>''bpass'' as text)as \"FRMPass\", vcpayeraccountexternalid as \"Payer Account\", vcpayeraddr as \"PayerVPA\", vcpayeeaccountexternalid as \"Payee Account\", vcpayeeaddr as \"PayeeVPA\", null as \"FailedRule\", cast(observations->''observations''->''payerVPA''->>''vpaName'' as text) as \"PayerName\",  cast(observations->''observations''->''payeeVPA''->>''vpaName'' as text) as \"PayeeName\" from transactions.trans where vcpayeeaccountexternalid = :useraddress and vcclassname  = :txnClass and (CAST(dttrxntime AS date) between CURRENT_DATE-1 and  CURRENT_DATE) order by dttrxntime desc;",
            "Both" : "select ilivemessageid as \"ILiveMessageID\", vcmsgid as \"UniqueID\", vcclassname as \"Class\", dttrxntime at time zone ''Asia/Kolkata'' at time zone :timeZone as \"Time\", dobservationamount as \"Amount\", score as \"Score\",  cast(result->''score''->>''bpass'' as text)as \"FRMPass\", vcpayeraccountexternalid as \"Payer Account\", vcpayeraddr as \"PayerVPA\", vcpayeeaccountexternalid as \"Payee Account\", vcpayeeaddr as \"PayeeVPA\", null as \"FailedRule\", cast(observations->''observations''->''payerVPA''->>''vpaName'' as text) as \"PayerName\",  cast(observations->''observations''->''payeeVPA''->>''vpaName'' as text) as \"PayeeName\" from transactions.trans where (vcpayeraccountexternalid = :useraddress or vcpayeeaccountexternalid = vcpayeraccountexternalid )  and vcclassname  = :txnClass and (CAST(dttrxntime AS date) between CURRENT_DATE-1 and CURRENT_DATE) order by dttrxntime desc;"
